"use client"

import { useState, useMemo } from "react"
import { Input } from "@/components/ui/input"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import Link from "next/link"
import Image from "next/image"
import { Search } from "lucide-react"
import { medicinesData } from "@/lib/medicines-data"

export default function MedicinesPage() {
  const [searchTerm, setSearchTerm] = useState("")
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null)

  const categories = useMemo(() => {
    const cats = new Set(medicinesData.map((m) => m.usedFor))
    return Array.from(cats)
  }, [])

  const filteredMedicines = useMemo(() => {
    return medicinesData.filter((medicine) => {
      const matchesSearch =
        medicine.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        medicine.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
        medicine.productDetails.generics.toLowerCase().includes(searchTerm.toLowerCase())
      const matchesCategory = !selectedCategory || medicine.usedFor === selectedCategory
      return matchesSearch && matchesCategory
    })
  }, [searchTerm, selectedCategory])

  return (
    <main className="min-h-screen bg-background py-12 px-4">
      <div className="max-w-6xl mx-auto">
        <div className="mb-12">
          <h1 className="text-4xl font-bold text-foreground mb-4">Medicine Database</h1>
          <p className="text-lg text-muted-foreground">
            Comprehensive information about medications, dosages, side effects, and interactions
          </p>
        </div>

        <div className="mb-8 space-y-6">
          <div className="relative">
            <Search className="absolute left-3 top-3 w-5 h-5 text-muted-foreground" />
            <Input
              placeholder="Search medicines, brands, or generics..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10 h-12 border-blue-200 focus:border-blue-600"
            />
          </div>

          <div>
            <h3 className="font-semibold text-foreground mb-3">Filter by Category</h3>
            <div className="flex flex-wrap gap-2">
              <button
                onClick={() => setSelectedCategory(null)}
                className={`px-4 py-2 rounded-full transition ${
                  selectedCategory === null ? "bg-blue-600 text-white" : "bg-blue-100 text-blue-700 hover:bg-blue-200"
                }`}
              >
                All
              </button>
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => setSelectedCategory(cat)}
                  className={`px-4 py-2 rounded-full transition ${
                    selectedCategory === cat ? "bg-blue-600 text-white" : "bg-blue-100 text-blue-700 hover:bg-blue-200"
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="mb-4 text-sm text-muted-foreground">{filteredMedicines.length} medicines found</div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredMedicines.map((medicine) => (
            <Link key={medicine.id} href={`/medicines/${medicine.id}`}>
              <Card className="h-full hover:shadow-lg transition cursor-pointer border-blue-100">
                <div className="w-full aspect-square bg-gray-100 overflow-hidden">
                  <Image
                    src={medicine.productImage || "/placeholder.svg"}
                    alt={medicine.title}
                    width={200}
                    height={200}
                    className="w-full h-full object-cover"
                  />
                </div>
                <CardHeader>
                  <CardTitle className="text-lg text-foreground line-clamp-2">{medicine.title}</CardTitle>
                  <CardDescription className="text-sm">{medicine.brand}</CardDescription>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div>
                    <p className="text-xs text-muted-foreground mb-1">Generic Name</p>
                    <p className="text-sm font-medium text-foreground line-clamp-2">
                      {medicine.productDetails.generics}
                    </p>
                  </div>
                  <div className="flex items-center gap-2 text-sm">
                    <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full">{medicine.usedFor}</span>
                  </div>
                  <div className="text-xs text-muted-foreground">
                    Requires Prescription: {medicine.productDetails.requiresPrescriptionYesNo}
                  </div>
                  <Button className="w-full bg-blue-600 hover:bg-blue-700 text-white mt-4">View Details →</Button>
                </CardContent>
              </Card>
            </Link>
          ))}
        </div>

        {filteredMedicines.length === 0 && (
          <div className="text-center py-12">
            <p className="text-muted-foreground text-lg">No medicines found matching your search.</p>
          </div>
        )}
      </div>
    </main>
  )
}
